script:
(function () {
  'use strict';
  // Packing lunch instead of buying it. Daily saving = bought price - packed price. Packed lunches a
  // year = days per week x weeks worked. Year y saving = daily saving x lunches x (1 + g)^(y - 1),
  // where g is the yearly rise in lunch prices. Each year's saving is invested in 12 equal
  // end-of-month amounts at the monthly rate (1 + R)^(1/12) - 1 for an annual return R.
  // Verified (scratchpad cu5/tests/lu.test.js): $14 vs $5, 4 days x 48 weeks = $1,728 a year
  // ($144 a month); at 6% for 10 years the closed form 144 x (q^120 - 1)/(q - 1), q = 1.06^(1/12),
  // = $23,396.18; 0% return = $17,280; 3% price rise makes year 2 save $1,779.84.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });

  function num(id) {
    var v = parseFloat(document.getElementById(id).value);
    return isNaN(v) ? NaN : v;
  }
  function set(id, text) { document.getElementById(id).textContent = text; }

  function project(buy, pack, lunches, R, years, g) {
    var q = Math.pow(1 + R, 1 / 12) - 1, bal = 0, total = 0, rows = [];
    for (var y = 1; y <= years; y++) {
      var lift = Math.pow(1 + g, y - 1), bought = buy * lunches * lift, packed = pack * lunches * lift, saved = bought - packed;
      for (var m = 0; m < 12; m++) bal = bal * (1 + q) + saved / 12;
      total += saved;
      rows.push({ year: y, bought: bought, packed: packed, saved: saved, total: total, balance: bal });
    }
    return { balance: bal, total: total, rows: rows };
  }

  function clear() {
    ['luValue', 'luYear1', 'luSaved', 'luGrowth', 'luPerLunch', 'luPerWeek', 'luPerMonth', 'luCount'].forEach(function (id) { set(id, '–'); });
    document.getElementById('luSchedule').innerHTML = '';
  }

  function update() {
    var buy = num('luBuy'), pack = num('luPack'), days = Math.round(num('luDays')), weeks = Math.round(num('luWeeks')),
        rate = num('luRate'), years = Math.round(num('luYears')), infl = num('luInflation');
    if (isNaN(infl)) infl = 0;
    var error = document.getElementById('luError'), msg = '';
    if ([buy, pack, days, weeks, rate, years].some(isNaN) || buy < 0 || pack < 0 || buy > 10000 || pack > 10000 || days < 0 || days > 7 ||
        weeks < 1 || weeks > 52 || rate < 0 || rate > 30 || years < 1 || years > 50 || infl < 0 || infl > 20) {
      msg = 'Enter lunch prices of $0 or more, 0 to 7 days a week, 1 to 52 weeks, a return from 0 to 30%, 1 to 50 years and a price rise from 0 to 20%.';
    } else if (pack >= buy) {
      msg = 'Packing only saves money when the packed lunch costs less than the bought one.';
    }
    error.hidden = !msg;
    if (msg) { error.textContent = msg; clear(); return; }
    var lunches = days * weeks, perLunch = buy - pack;
    var res = project(buy, pack, lunches, rate / 100, years, infl / 100);
    set('luValueLabel', 'Invested savings after ' + years + (years === 1 ? ' year' : ' years'));
    set('luValue', money.format(res.balance));
    set('luYear1', money.format(res.rows[0].saved));
    set('luSaved', money.format(res.total));
    set('luGrowth', money.format(res.balance - res.total));
    set('luPerLunch', money.format(perLunch));
    set('luPerWeek', money.format(perLunch * days));
    set('luPerMonth', money.format(res.rows[0].saved / 12));
    set('luCount', String(lunches));
    document.getElementById('luSchedule').innerHTML = res.rows.map(function (row) {
      return '<tr><td>' + row.year + '</td><td>' + money.format(row.bought) + '</td><td>' + money.format(row.packed) + '</td><td>' +
             money.format(row.saved) + '</td><td>' + money.format(row.total) + '</td><td>' + money.format(row.balance) + '</td></tr>';
    }).join('');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('luForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
